            if (ones == 9) q_reg[3:0] <= 4'd0;
            if (tens == 9) q_reg[7:4] <= 4'd0;
            if (hundreds == 9) q_reg[11:8] <= 4'd0;
            if (thousands == 9) q_reg[15:12] <= 4'd0;
        end
    end
    assign ena = ena_ones_tens_hundreds | ena_tens_hundreds_thousands;
    assign q = q_reg;
endmodule
